{"command":"cd .. && node --input-type=module - <<'NODE'
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { parsePo } from './tools/i18n-engine/src/po.ts';
const root = process.cwd();
const required = [
  'sidebar.css',
  'sidebar.apiGroups.ai',
  'sidebar.apiGroups.bundlers',
  'sidebar.apiGroups.design',
  'sidebar.apiGroups.formats',
  'sidebar.apiGroups.packages',
  'sidebar.apiGroups.platforms',
  'sidebar.apiGroups.plugins',
  'sidebar.apiGroups.renderers',
  'sidebar.apiGroups.tools',
];
const bad = [];
for (const dirent of readdirSync(join(root, 'l10n'), { withFileTypes: true })) {
  if (!dirent.isDirectory()) continue;
  const entries = parsePo(readFileSync(join(root, 'l10n', dirent.name, 'docs.chrome.po'), 'utf8'));
  const byContext = new Map(entries.filter((entry) => !entry.obsolete).map((entry) => [entry.msgctxt, entry]));
  for (const key of required) {
    const entry = byContext.get(`docs.chrome:${key}`);
    if (!entry || entry.msgstr === '') bad.push(`${dirent.name}:${key}:missing`);
  }
  const ai = byContext.get('docs.chrome:sidebar.apiGroups.ai');
  if (ai?.msgstr !== 'AI') bad.push(`${dirent.name}:sidebar.apiGroups.ai:${ai?.msgstr ?? '<missing>'}`);
}
if (bad.length > 0) {
  console.error(bad.join('\n'));
  process.exit(1);
}
console.log('All chrome sidebar labels are present; AI is protected in every locale.');
